// Jonker-Volgenant LAP, dense square double matrix, column-major input (Fortran)
// Adapted from the classic lapjv implementation (public domain / BSD style algorithm).
#include <vector>
#include <cmath>
#include <cstdint>
#include <algorithm>
#include <cstring>
#include <iostream>
#include <chrono>
#include <random>

using namespace std;

static const double INF = 1e18;

// cost is column-major: cost[j*n + i] OR row-major cost[i*n+j]? We'll use row-major cost[i*n+j]
// Returns col_of_row
void lapjv(const double* cost, int n, int* rowsol) {
    vector<double> u(n, 0.0), v(n, 0.0), d(n);
    vector<int> colsol(n, -1), pred(n), free_rows(n);
    vector<char> scanned(n);

    auto C = [&](int i, int j) -> double { return cost[i * n + j]; };

    // column reduction
    vector<int> rowsol_tmp(n, -1);
    for (int j = n - 1; j >= 0; --j) {
        double minv = C(0, j);
        int imin = 0;
        for (int i = 1; i < n; ++i) {
            double cij = C(i, j);
            if (cij < minv) { minv = cij; imin = i; }
        }
        v[j] = minv;
        if (rowsol_tmp[imin] == -1) {
            rowsol_tmp[imin] = j;
            colsol[j] = imin;
        }
    }
    int numfree = 0;
    for (int i = 0; i < n; ++i) {
        int j = rowsol_tmp[i];
        if (j == -1) {
            free_rows[numfree++] = i;
        } else {
            double minv = INF;
            for (int j2 = 0; j2 < n; ++j2) if (j2 != j) {
                double red = C(i, j2) - v[j2];
                if (red < minv) minv = red;
            }
            v[j] = C(i, j) - minv;
        }
        rowsol[i] = rowsol_tmp[i];
    }

    // augmenting row reduction, 2 phases
    for (int phase = 0; phase < 2; ++phase) {
        int k = 0;
        int prev = numfree;
        numfree = 0;
        while (k < prev) {
            int i = free_rows[k++];
            double umin = C(i, 0) - v[0];
            int j1 = 0;
            double usub = INF;
            int j2 = 0;
            for (int j = 1; j < n; ++j) {
                double h = C(i, j) - v[j];
                if (h < usub) {
                    if (h >= umin) {
                        usub = h; j2 = j;
                    } else {
                        usub = umin; j2 = j1; umin = h; j1 = j;
                    }
                }
            }
            int i0 = colsol[j1];
            if (umin < usub) {
                v[j1] -= (usub - umin);
            } else if (i0 >= 0 && j2 != j1) {
                j1 = j2;
                i0 = colsol[j1];
            }
            rowsol[i] = j1;
            colsol[j1] = i;
            if (i0 >= 0) {
                if (umin < usub) {
                    free_rows[--k] = i0;
                } else {
                    free_rows[numfree++] = i0;
                }
            }
        }
    }

    // augmentation
    for (int f = 0; f < numfree; ++f) {
        int freerow = free_rows[f];
        for (int j = 0; j < n; ++j) {
            d[j] = C(freerow, j) - v[j];
            pred[j] = freerow;
            scanned[j] = 0;
        }
        int endofpath = -1;
        double minv = 0;
        int remaining = n;
        while (remaining--) {
            minv = INF;
            int jmin = -1;
            for (int j = 0; j < n; ++j) if (!scanned[j] && d[j] < minv) {
                minv = d[j]; jmin = j;
            }
            if (jmin < 0) break;
            scanned[jmin] = 1;
            int i = colsol[jmin];
            if (i < 0) { endofpath = jmin; break; }
            double cred = C(i, jmin) - v[jmin] - minv;
            for (int j = 0; j < n; ++j) if (!scanned[j]) {
                double h = C(i, j) - v[j] - cred;
                if (h < d[j]) { d[j] = h; pred[j] = i; }
            }
        }
        for (int j = 0; j < n; ++j) if (scanned[j]) v[j] += d[j] - minv;
        int i = -1, j = endofpath;
        while (i != freerow) {
            i = pred[j];
            colsol[j] = i;
            int h = rowsol[i];
            rowsol[i] = j;
            j = h;
        }
    }
}

int main() {
    int n = 600;
    mt19937 rng(1);
    uniform_real_distribution<double> dist(0.0, 1.0);
    vector<double> M(n * n);
    for (auto& x : M) x = dist(rng);
    vector<int> sol(n);
    // warmup
    lapjv(M.data(), n, sol.data());
    auto t0 = chrono::high_resolution_clock::now();
    int reps = 3;
    for (int r = 0; r < reps; ++r) lapjv(M.data(), n, sol.data());
    auto t1 = chrono::high_resolution_clock::now();
    double sec = chrono::duration<double>(t1 - t0).count() / reps;
    double cost = 0;
    for (int i = 0; i < n; ++i) cost += M[i * n + sol[i]];
    cout << "time " << sec << " cost " << cost << "\n";
}
