#include <vector>
#include <cmath>
#include <cstdint>
#include <algorithm>
#include <iostream>
#include <chrono>
#include <random>
#include <cstring>
using namespace std;

// Bertsekas epsilon-scaling auction for minimization, square dense.
// Returns row->col. eps_final should be < (min positive reduced gap)/n for exactness on integer costs.
// For float costs we scale to integers externally.
bool auction(const double* cost, int n, int* assign, double eps_final) {
    vector<double> price(n, 0.0);
    vector<int> owner(n, -1);
    vector<int> q(n * 8);
    vector<double> val(n);

    double mx = -1e300, mn = 1e300;
    for (int i = 0; i < n * n; ++i) {
        double v = cost[i];
        if (v > mx) mx = v;
        if (v < mn) mn = v;
    }
    double eps = (mx - mn) / 4.0;
    if (eps < eps_final) eps = eps_final;

    while (true) {
        fill(owner.begin(), owner.end(), -1);
        fill(assign, assign + n, -1);
        int qh = 0, qt = n;
        for (int i = 0; i < n; ++i) q[i] = i;
        int unassigned = n;
        long long guard = 0;
        long long max_guard = (long long)n * n * 8;
        while (unassigned > 0) {
            if (++guard > max_guard) return false;
            if (qh == qt) return false;
            int i = q[qh++];
            if (qh >= (int)q.size() - n) {
                // compact
                int sz = qt - qh;
                memmove(q.data(), q.data() + qh, sz * sizeof(int));
                qh = 0; qt = sz;
            }
            // best and second best of -cost - price
            const double* row = cost + (size_t)i * n;
            int best_j = 0;
            double best = -row[0] - price[0];
            double second = -1e300;
            for (int j = 1; j < n; ++j) {
                double v = -row[j] - price[j];
                if (v > best) { second = best; best = v; best_j = j; }
                else if (v > second) second = v;
            }
            double bid = price[best_j] + (best - second) + eps;
            int prev = owner[best_j];
            if (prev >= 0) {
                assign[prev] = -1;
                if (qt >= (int)q.size()) q.resize(q.size() * 2);
                q[qt++] = prev;
            } else {
                unassigned--;
            }
            owner[best_j] = i;
            assign[i] = best_j;
            price[best_j] = bid;
        }
        if (eps <= eps_final * 1.0000001) break;
        eps *= 0.2;
        if (eps < eps_final) eps = eps_final;
    }
    return true;
}

int main() {
    int n = 600;
    mt19937 rng(1);
    uniform_real_distribution<double> dist(0.0, 1.0);
    vector<double> M(n * (size_t)n);
    for (auto& x : M) x = dist(rng);
    // scale to int-like
    double scale = 1e6;
    for (auto& x : M) x = std::round(x * scale);
    vector<int> sol(n);
    bool ok = auction(M.data(), n, sol.data(), 1.0 / (n + 1));
    cout << "ok " << ok << "\n";
    auto t0 = chrono::high_resolution_clock::now();
    int reps = 3;
    for (int r = 0; r < reps; ++r) auction(M.data(), n, sol.data(), 1.0 / (n + 1));
    auto t1 = chrono::high_resolution_clock::now();
    cout << "time " << chrono::duration<double>(t1-t0).count()/reps << "\n";
}
