// Fast dense LAP (Jonker-Volgenant style) with column-list Dijkstra.
// Input: row-major double cost[n*n]. Output: rowsol[i] = assigned column.
#include <vector>
#include <cstdint>
#include <algorithm>
#include <iostream>
#include <chrono>
#include <random>
#include <cstring>
#include <cmath>
using namespace std;

static constexpr double BIG = 1e18;

void lap(const double* cost, int n, int* rowsol) {
    vector<double> v(n), d(n), u(n, 0.0);
    vector<int> colsol(n, -1), pred(n), free_rows(n);
    vector<int> todo(n);          // columns not yet scanned, dense list
    vector<char> in_todo(n, 1);

    auto C = [&](int i, int j) -> double { return cost[(size_t)i * n + j]; };

    // column reduction (reverse so first columns get preference on ties, matching common impl)
    for (int j = n - 1; j >= 0; --j) {
        double minv = C(0, j);
        int imin = 0;
        for (int i = 1; i < n; ++i) {
            double cij = C(i, j);
            if (cij < minv) { minv = cij; imin = i; }
        }
        v[j] = minv;
        if (rowsol[imin] < 0) {
            rowsol[imin] = j;
            colsol[j] = imin;
        } else {
            // conflict: leave this column free (row already matched to a later column)
        }
    }

    int numfree = 0;
    for (int i = 0; i < n; ++i) {
        int j = rowsol[i];
        if (j < 0) {
            free_rows[numfree++] = i;
        } else {
            double minv = BIG;
            for (int j2 = 0; j2 < n; ++j2) if (j2 != j) {
                double red = C(i, j2) - v[j2];
                if (red < minv) minv = red;
            }
            v[j] = C(i, j) - minv;
        }
    }

    // augmenting row reduction
    for (int phase = 0; phase < 2; ++phase) {
        int k = 0, prev = numfree;
        numfree = 0;
        while (k < prev) {
            int i = free_rows[k++];
            double umin = C(i, 0) - v[0];
            int j1 = 0;
            double usub = BIG;
            int j2 = 0;
            for (int j = 1; j < n; ++j) {
                double h = C(i, j) - v[j];
                if (h < usub) {
                    if (h >= umin) { usub = h; j2 = j; }
                    else { usub = umin; j2 = j1; umin = h; j1 = j; }
                }
            }
            int i0 = colsol[j1];
            double diff = usub - umin;
            if (diff > 0) {
                v[j1] -= diff;
            } else if (i0 >= 0 && j2 != j1) {
                j1 = j2;
                i0 = colsol[j1];
            }
            rowsol[i] = j1;
            colsol[j1] = i;
            if (i0 >= 0) {
                if (diff > 0) free_rows[--k] = i0;
                else free_rows[numfree++] = i0;
            }
        }
    }

    // augmentation with TODO list (scan only remaining columns)
    vector<int> scan_idx(n);
    for (int f = 0; f < numfree; ++f) {
        int freerow = free_rows[f];
        int tsize = n;
        for (int j = 0; j < n; ++j) {
            todo[j] = j;
            d[j] = C(freerow, j) - v[j];
            pred[j] = freerow;
        }
        int endofpath = -1;
        double minv = 0;
        int ready_end = 0; // columns with d[j] == current threshold, not used
        // We'll repeatedly find min among todo[0..tsize)
        while (true) {
            // find min in todo
            minv = BIG;
            int jpos = -1;
            for (int t = 0; t < tsize; ++t) {
                int j = todo[t];
                if (d[j] < minv) { minv = d[j]; jpos = t; }
            }
            int jmin = todo[jpos];
            // remove jmin from todo (swap with last)
            todo[jpos] = todo[--tsize];
            int i = colsol[jmin];
            if (i < 0) { endofpath = jmin; break; }
            double cred = C(i, jmin) - v[jmin] - minv;
            const double* row = cost + (size_t)i * n;
