        // dual update: all columns not in todo were scanned
        // scanned = those removed from todo, including endofpath
        // We didn't track scanned set explicitly. Track via a stamp.
        // Redo dual update by comparing? We lost scanned set.
        // Fix: use a scan stamp array.
        // For now, store scanned in a side array during the loop — rewrite quickly.
        (void)endofpath;
    }
}

// Clean version
void lap2(const double* cost, int n, int* rowsol) {
    vector<double> v(n), d(n);
    vector<int> colsol(n, -1), pred(n), free_rows(n), todo(n);
    vector<int> scanned_stamp(n, 0);
    int stamp = 1;

    // init rowsol
    for (int i = 0; i < n; ++i) rowsol[i] = -1;

    for (int j = n - 1; j >= 0; --j) {
        const double* colptr_scan = nullptr;
        double minv = cost[j];
        int imin = 0;
        for (int i = 1; i < n; ++i) {
            double cij = cost[(size_t)i * n + j];
            if (cij < minv) { minv = cij; imin = i; }
        }
        v[j] = minv;
        if (rowsol[imin] < 0) {
            rowsol[imin] = j;
            colsol[j] = imin;
        }
    }
    int numfree = 0;
    for (int i = 0; i < n; ++i) {
        int j = rowsol[i];
        if (j < 0) free_rows[numfree++] = i;
        else {
            double minv = BIG;
            const double* row = cost + (size_t)i * n;
            for (int j2 = 0; j2 < n; ++j2) if (j2 != j) {
                double red = row[j2] - v[j2];
                if (red < minv) minv = red;
            }
            v[j] = row[j] - minv;
        }
    }

    for (int phase = 0; phase < 2; ++phase) {
        int k = 0, prev = numfree;
        numfree = 0;
        while (k < prev) {
            int i = free_rows[k++];
            const double* row = cost + (size_t)i * n;
            double umin = row[0] - v[0];
            int j1 = 0;
            double usub = BIG;
            int j2 = 0;
            for (int j = 1; j < n; ++j) {
                double h = row[j] - v[j];
                if (h < usub) {
                    if (h >= umin) { usub = h; j2 = j; }
                    else { usub = umin; j2 = j1; umin = h; j1 = j; }
                }
            }
            int i0 = colsol[j1];
            double diff = usub - umin;
            if (diff > 0.0) v[j1] -= diff;
            else if (i0 >= 0 && j2 != j1) { j1 = j2; i0 = colsol[j1]; }
            rowsol[i] = j1;
            colsol[j1] = i;
            if (i0 >= 0) {
                if (diff > 0.0) free_rows[--k] = i0;
                else free_rows[numfree++] = i0;
            }
        }
    }

    vector<int> scanned(n);
    int nscanned = 0;
    for (int f = 0; f < numfree; ++f) {
        int freerow = free_rows[f];
        int tsize = n;
        const double* frow = cost + (size_t)freerow * n;
        for (int j = 0; j < n; ++j) {
            todo[j] = j;
            d[j] = frow[j] - v[j];
            pred[j] = freerow;
        }
        nscanned = 0;
        int endofpath = -1;
        double minv = 0;
        while (true) {
            minv = BIG;
            int jpos = 0;
            for (int t = 0; t < tsize; ++t) {
                double dj = d[todo[t]];
                if (dj < minv) { minv = dj; jpos = t; }
            }
            int jmin = todo[jpos];
            todo[jpos] = todo[--tsize];
            scanned[nscanned++] = jmin;
            int i = colsol[jmin];
            if (i < 0) { endofpath = jmin; break; }
            double cred = cost[(size_t)i * n + jmin] - v[jmin] - minv;
            const double* row = cost + (size_t)i * n;
            for (int t = 0; t < tsize; ++t) {
                int j = todo[t];
                double h = row[j] - v[j] - cred;
                if (h < d[j]) { d[j] = h; pred[j] = i; }
            }
        }
        for (int s = 0; s < nscanned; ++s) {
            int j = scanned[s];
            v[j] += d[j] - minv;
        }
        int i = -1, j = endofpath;
        while (i != freerow) {
            i = pred[j];
            colsol[j] = i;
            int h = rowsol[i];
            rowsol[i] = j;
            j = h;
        }
    }
}

