#include <vector>
#include <cmath>
#include <cstdint>
#include <algorithm>
#include <iostream>
#include <chrono>
#include <random>
#include <cstring>
using namespace std;

struct Pt { double x, y; };

// 2D auction using brute force (baseline) then we'll add spatial if needed.
// For exactness on float distances, scale costs to int via rounding of distance*SCALE.

bool auction_pts(const Pt* X, const Pt* Y, int n, int* assign, double eps_final) {
    vector<double> price(n, 0.0);
    vector<int> owner(n, -1);
    vector<int> q(n * 4);
    double eps = 0.5; // initial, distances are O(1)
    while (true) {
        fill(owner.begin(), owner.end(), -1);
        int qh = 0, qt = n;
        for (int i = 0; i < n; ++i) q[i] = i;
        int unassigned = n;
        long long guard = 0;
        long long maxg = (long long)n * n * 4;
        while (unassigned) {
            if (++guard > maxg) return false;
            int i = q[qh++];
            if (qh > (int)q.size()/2) {
                int sz = qt - qh;
                memmove(q.data(), q.data()+qh, sz*sizeof(int));
                qh=0; qt=sz;
            }
            double xi=X[i].x, yi=X[i].y;
            int best_j=0;
            double best = -1e300, second=-1e300;
            for (int j=0;j<n;++j) {
                double dx=xi-Y[j].x, dy=yi-Y[j].y;
                double v = -sqrt(dx*dx+dy*dy) - price[j];
                if (v>best) { second=best; best=v; best_j=j; }
                else if (v>second) second=v;
            }
            double bid = price[best_j] + (best-second) + eps;
            int prev = owner[best_j];
            if (prev>=0) {
                if (qt>=(int)q.size()) q.resize(q.size()*2);
                q[qt++]=prev;
            } else unassigned--;
            owner[best_j]=i;
            assign[i]=best_j;
            price[best_j]=bid;
        }
        if (eps <= eps_final*1.0000001) break;
        eps *= 0.25;
        if (eps < eps_final) eps = eps_final;
    }
    return true;
}

int main() {
    int n=600;
    mt19937 rng(1);
    uniform_real_distribution<double> dist(0,1);
    vector<Pt> X(n), Y(n);
    for (int i=0;i<n;i++) { X[i]={dist(rng),dist(rng)}; Y[i]={dist(rng),dist(rng)}; }
    vector<int> asg(n);
    bool ok=auction_pts(X.data(), Y.data(), n, asg.data(), 1e-9);
    cout<<"ok "<<ok<<"\n";
    auto t0=chrono::high_resolution_clock::now();
    int reps=3;
    for(int r=0;r<reps;r++) auction_pts(X.data(), Y.data(), n, asg.data(), 1e-9);
    auto t1=chrono::high_resolution_clock::now();
    cout<<"time "<<chrono::duration<double>(t1-t0).count()/reps<<"\n";
    // cost
    double c=0;
    for(int i=0;i<n;i++){ double dx=X[i].x-Y[asg[i]].x, dy=X[i].y-Y[asg[i]].y; c+=sqrt(dx*dx+dy*dy); }
    cout<<"cost "<<c<<"\n";
}
