// Jonker-Volgenant with integer costs, column-major access optimized.
// Based on the public-domain lapmod/lapjv structure.
#include <cstdint>
#include <vector>
#include <algorithm>
#include <iostream>
#include <chrono>
#include <random>
#include <cstring>
#include <cmath>
using namespace std;

static constexpr int64_t INF = (int64_t)4e18;

// cost row-major int64
void lapjv_int(const int64_t* cost, int n, int* rowsol) {
    vector<int64_t> v(n, 0), d(n);
    vector<int> colsol(n, -1), pred(n), free_rows(n), todo(n), scanned(n);

    for (int i = 0; i < n; ++i) rowsol[i] = -1;

    // column reduction
    for (int j = n - 1; j >= 0; --j) {
        int64_t minv = cost[j];
        int imin = 0;
        for (int i = 1; i < n; ++i) {
            int64_t cij = cost[(size_t)i * n + j];
