static PyObject* py_solve(PyObject* self, PyObject* args) {
    PyObject* obj;
    double scale;
    if (!PyArg_ParseTuple(args, "Od", &obj, &scale)) return NULL;
    PyArrayObject* arr = (PyArrayObject*)PyArray_FROM_OTF(obj, NPY_FLOAT64, NPY_ARRAY_IN_ARRAY);
    if (!arr) return NULL;
    if (PyArray_NDIM(arr) != 2) {
        Py_DECREF(arr);
        PyErr_SetString(PyExc_ValueError, "expected 2d");
        return NULL;
    }
    int n = (int)PyArray_DIM(arr, 0);
    int m = (int)PyArray_DIM(arr, 1);
    if (n != m) {
        Py_DECREF(arr);
        PyErr_SetString(PyExc_ValueError, "square only");
        return NULL;
    }
    const double* M = (const double*)PyArray_DATA(arr);
    std::vector<int64_t> cost((size_t)n * n);
    // handle non-contiguous by strides
    npy_intp stride0 = PyArray_STRIDE(arr, 0) / (npy_intp)sizeof(double);
    npy_intp stride1 = PyArray_STRIDE(arr, 1) / (npy_intp)sizeof(double);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            double v = M[i * stride0 + j * stride1];
            cost[(size_t)i * n + j] = (int64_t)llround(v * scale);
        }
    }
    std::vector<int> rowsol(n);
    lapjv_int(cost.data(), n, rowsol.data());
    Py_DECREF(arr);
    npy_intp dims[1] = {n};
    PyObject* out = PyArray_SimpleNew(1, dims, NPY_INT32);
    if (!out) return NULL;
    int32_t* o = (int32_t*)PyArray_DATA((PyArrayObject*)out);
    for (int i = 0; i < n; ++i) o[i] = rowsol[i];
    return out;
}

static PyMethodDef methods[] = {
    {"solve", py_solve, METH_VARARGS, "solve"},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "lapext", NULL, -1, methods
};
PyMODINIT_FUNC PyInit_lapext(void) {
    import_array();
