    for (int i = 0; i < n; ++i) {
        rowsol[i] = -1;
        colsol[i] = -1;
        u[i] = 0;
        v[i] = BIG;
    }
    // COLUMN REDUCTION
    for (int j = n - 1; j >= 0; --j) {
        double min = BIG;
        int imin = 0;
        for (int i = 0; i < n; ++i) {
            double c = cost[(size_t)i * n + j];
            if (c < min) { min = c; imin = i; }
        }
        v[j] = min;
        if (rowsol[imin] == -1) {
            rowsol[imin] = j;
            colsol[j] = imin;
        }
    }
    // REDUCTION TRANSFER
    for (int i = 0; i < n; ++i) {
        if (rowsol[i] == -1) free_rows[numfree++] = i;
        else {
            int j1 = rowsol[i];
            double min = BIG;
            const double* row = cost + (size_t)i * n;
            for (int j = 0; j < n; ++j) if (j != j1) {
                double red = row[j] - v[j];
                if (red < min) min = red;
            }
            v[j1] -= min;
        }
    }
    // AUGMENTING ROW REDUCTION
    int loopcnt = 0;
    for (int f = 0; f < numfree; ) {
        int freerow = free_rows[f];
        const double* row = cost + (size_t)freerow * n;
        double umin = row[0] - v[0];
        int j1 = 0, j2 = -1;
        double usubmin = BIG;
        for (int j = 1; j < n; ++j) {
