        int i0 = colsol[j1];
        double vj1new = v[j1] - (usubmin - umin);
        bool vchange = vj1new < v[j1];
        if (vchange) v[j1] = vj1new;
        else if (i0 >= 0 && j2 >= 0) {
            j1 = j2;
