            else free_rows[f++] = i0; // defer? standard increments differently
            // The classic code has two phases. This simplified version may be wrong.
            // We'll use a cleaner known implementation below instead.
        } else {
            f++;
        }
        if (++loopcnt > n * n) break;
    }
    return 0;
