        while (true) {
            minv = INF;
            int jpos = 0;
            for (int t = 0; t < tsize; ++t) {
                double dj = d[todo[t]];
                if (dj < minv) { minv = dj; jpos = t; }
            }
            int jmin = todo[jpos];
            todo[jpos] = todo[--tsize];
            scanned[nscanned++] = jmin;
            int i = colsol[jmin];
            if (i < 0) { endofpath = jmin; break; }
            double cred = cost[(size_t)i * n + jmin] - v[jmin] - minv;
            const double* row = cost + (size_t)i * n;
            for (int t = 0; t < tsize; ++t) {
                int j = todo[t];
                double h = row[j] - v[j] - cred;
                if (h < d[j]) { d[j] = h; pred[j] = i; }
            }
        }
        for (int s = 0; s < nscanned; ++s) v[scanned[s]] += d[scanned[s]] - minv;
        int i = -1, j = endofpath;
        while (i != freerow) {
            i = pred[j];
            colsol[j] = i;
            int h = rowsol[i];
            rowsol[i] = j;
            j = h;
        }
    }
    (void)free_after_col;
}

int main() {
    int n = 600;
    mt19937 rng(1);
    uniform_real_distribution<double> unif(0, 1);
    vector<double> M(n * (size_t)n);
    for (auto& x : M) x = unif(rng);
    vector<int> sol(n);
    int nf=0;
    lap_ref(M.data(), n, sol.data(), &nf);
    cout << "numfree after row reduction " << nf << " / " << n << "\n";
    // euclidean-like
    vector<double> X(n*2), Y(n*2);
    for (int i=0;i<n*2;i++) { X[i]=unif(rng); Y[i]=unif(rng); }
    for (int i=0;i<n;i++) for (int j=0;j<n;j++) {
        double dx=X[2*i]-Y[2*j], dy=X[2*i+1]-Y[2*j+1];
        M[(size_t)i*n+j]=sqrt(dx*dx+dy*dy);
    }
    lap_ref(M.data(), n, sol.data(), &nf);
    cout << "eucl numfree " << nf << "\n";
    auto t0=chrono::high_resolution_clock::now();
    for(int r=0;r<4;r++) lap_ref(M.data(), n, sol.data(), &nf);
    auto t1=chrono::high_resolution_clock::now();
    cout << "eucl time " << chrono::duration<double>(t1-t0).count()/4 << "\n";
}
