{"command":"cat > lapjv_full.cpp << 'EOF'
// Jonker-Volgenant dense LAP, translated from the classic lap.cpp
// (Jonker & Volgenant 1987 / public-domain numerical recipe style).
// cost is row-major double[n*n]. Returns rowsol[i] = column assigned to row i.
#include <cmath>
#include <cstdint>
#include <cstdlib>
#include <cstring>
#include <vector>
#include <iostream>
#include <chrono>
#include <random>
using namespace std;

static constexpr double FP_BIG = 1e18;

int lapjv(int dim, const double* assigncost, int* rowsol, int* colsol) {
    vector<double> u(dim), v(dim), d(dim);
    vector<int> pred(dim), free(dim), collist(dim), matches(dim);
    vector<char> colactive(dim);
    int i, j, imin, numfree = 0, prvnumfree, f, i0, k, freerow;
    int j1, j2, endofpath, last, low, up;
    double min, h, umin, usubmin, v2;

    for (i = 0; i < dim; i++) {
        rowsol[i] = -1;
        colsol[i] = -1;
        u[i] = 0.0;
        v[i] = FP_BIG;
    }

    // COLUMN REDUCTION
    for (j = dim - 1; j >= 0; j--) {
        min = assigncost[j];
        imin = 0;
        for (i = 1; i < dim; i++) {
            double c = assigncost[(size_t)i * dim + j];
            if (c < min) { min = c; imin = i; }
        }
        v[j] = min;
        if (rowsol[imin] == -1) {
            rowsol[imin] = j;
            colsol[j] = imin;
        } else {
            // unique? if another column already claimed imin, mark this column for later by setting v big? 
            // classic: if u[imin] or row already assigned, add to "unique" handling via matches
            colsol[j] = -1; // leave unmatched if conflict; rowsol stays with previous
        }
    }
    // The classic algorithm tracks uniqueness differently. If two columns share the min row,
    // only the later-processed (smaller j, since we go reverse) keeps it if we overwrite.
    // We currently keep the first (larger j). That's fine.

    // REDUCTION TRANSFER
    for (i = 0; i < dim; i++) {
        if (rowsol[i] == -1)
            free[numfree++] = i;
        else {
            j1 = rowsol[i];
            min = FP_BIG;
            const double* row = assigncost + (size_t)i * dim;
            for (j = 0; j < dim; j++) if (j != j1) {
                h = row[j] - v[j];
                if (h < min) min = h;
            }
            v[j1] = row[j1] - min;
        }
    }

    // AUGMENTING ROW REDUCTION
    for (int loopcnt = 0; loopcnt < 2; loopcnt++) {
        k = 0;
        prvnumfree = numfree;
        numfree = 0;
        while (k < prvnumfree) {
            i = free[k++];
            umin = assigncost[i * (size_t)dim] - v[0];
            j1 = 0;
            usubmin = FP_BIG;
            j2 = -1;
            const double* row = assigncost + (size_t)i * dim;
            for (j = 1; j < dim; j++) {
                h = row[j] - v[j];
                if (h < usubmin) {
                    if (h >= umin) {
                        usubmin = h;
                        j2 = j;
                    } else {
                        usubmin = umin;
                        umin = h;
                        j2 = j1;
                        j1 = j;
                    }
                }
            }
            i0 = colsol[j1];
            if (umin < usubmin) {
                v[j1] = v[j1] - (usubmin - umin);
            } else if (i0 >= 0 && j2 >= 0) {
                j1 = j2;
                i0 = colsol[j1];
            }
            rowsol[i] = j1;
            colsol[j1] = i;
            if (i0 >= 0) {
                if (umin < usubmin)
                    free[--k] = i0;
                else
                    free[numfree++] = i0;
            }
        }
    }

    // AUGMENT SOLUTION for each free row
    for (f = 0; f < numfree; f++) {
        freerow = free[f];
        const double* frow = assigncost + (size_t)freerow * dim;
        for (j = 0; j < dim; j++) {
            d[j] = frow[j] - v[j];
            pred[j] = freerow;
            collist[j] = j;
        }
        low = 0;
        up = 0;
        unassigned_found:
        last = low - 1;
        min = d[collist[up++]];
        for (k = up; k < dim; k++) {
            j = collist[k];
            h = d[j];
            if (h <= min) {
                if (h < min) {
                    up = low;
                    min = h;
                }
                collist[k] = collist[up];
                collist[up++] = j;
            }
        }
        for (k = low; k < up; k++) {
            if (colsol[collist[k]] < 0) {
                endofpath = collist[k];
                goto augment;
            }
        }
        // update distances
        last = low - 1;
        // no: classic uses a "ready" set [low, up) of columns at current min, and scans them to update
        {
            int up_new_start = up;
            // We'll process columns in [low, up)
            for (int kk = low; kk < up; kk++) {
                j1 = collist[kk];
                i = colsol[j1];
                const double* row = assigncost + (size_t)i * dim;
                double cred_base = row[j1] - v[j1] - min;
                for (int k2 = up; k2 < dim; k2++) {
                    j = collist[k2];
                    h = row[j] - v[j] - cred_base;
                    if (h < d[j]) {
                        d[j] = h;
                        pred[j] = i;
                        if (h == min) {
                            if (colsol[j] < 0) {
                                endofpath = j;
                                goto augment;
                            }
                            collist[k2] = collist[up];
                            collist[up++] = j;
                        }
                    }
                }
            }
        }
        // scan remaining for new min
        if (up == dim) {
            // no unassigned? shouldn't happen
            endofpath = collist[0];
            goto augment;
        }
        low = up;
        goto unassigned_found;

    augment:
        // update column prices
        for (k = 0; k < up; k++) {  // columns considered? classic updates all scanned
            // The columns whose d was finalized are those removed from the candidate list,
            // i.e. indices < low at each stage, plus the final [low, up) at min.
            // This simplified update is NOT exactly the classic dual update.
            // We'll do a conservative update over all columns that have been moved before `up`
            // which at termination includes all scanned columns if we only move scanned ones into [0, up).
            j1 = collist[k];
            v[j1] += d[j1] - min;
        }
        // augment along path
        do {
            i = pred[endofpath];
            colsol[endofpath] = i;
            j1 = endofpath;
            endofpath = rowsol[i];
            rowsol[i] = j1;
        } while (i != freerow);
    }
    return numfree;
}

int main() {
    int n = 600;
    mt19937 rng(1);
    uniform_real_distribution<double> unif(0, 1);
    vector<double> X(n * 2), Y(n * 2), M(n * (size_t)n);
    for (int i = 0; i < n * 2; i++) { X[i] = unif(rng); Y[i] = unif(rng); }
    for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) {
        double dx = X[2 * i] - Y[2 * j], dy = X[2 * i + 1] - Y[2 * j + 1];
        M[(size_t)i * n + j] = sqrt(dx * dx + dy * dy);
    }
    vector<int> rowsol(n), colsol(n);
    auto t0 = chrono::high_resolution_clock::now();
    int nf = lapjv(n, M.data(), rowsol.data(), colsol.data());
    auto t1 = chrono::high_resolution_clock::now();
    double cost = 0;
    for (int i = 0; i < n; i++) cost += M[(size_t)i * n + rowsol[i]];
    cout << "time " << chrono::duration<double>(t1 - t0).count() << " cost " << cost << " numfree_in " << nf << "\n";
    // check permutation
    vector<int> seen(n, 0);
    int bad = 0;
    for (int i = 0; i < n; i++) {
        if (rowsol[i] < 0 || rowsol[i] >= n || seen[rowsol[i]]++) bad++;
    }
    cout << "bad " << bad << "\n";
}
