#include <cmath>
#include <cstdint>
#include <vector>
#include <iostream>
#include <chrono>
#include <random>
using namespace std;

// Faithful dense JV. Returns 0 on success.
// rowsol[i] = column for row i.
int lap(int n, const double* C, int* rowsol) {
    const double BIG = 1e18;
    vector<double> u(n, 0.0), v(n), d(n);
    vector<int> colsol(n, -1), pred(n), free_rows(n);
    vector<int> collist(n);
    vector<char> in_path(n);

    for (int i = 0; i < n; ++i) rowsol[i] = -1;
    for (int j = 0; j < n; ++j) v[j] = BIG;

    // COLUMN REDUCTION
    for (int j = n - 1; j >= 0; --j) {
        double minv = C[j];
        int imin = 0;
        for (int i = 1; i < n; ++i) {
            double c = C[(size_t)i * n + j];
            if (c < minv) { minv = c; imin = i; }
        }
        v[j] = minv;
        if (u[imin] == 0.0 && rowsol[imin] == -1) {
            // mark row as matched; classic also sets u[imin] = 1 as a flag in some versions
            rowsol[imin] = j;
            colsol[j] = imin;
            u[imin] = BIG; // temporary flag that row is matched during column reduction? 
            // DON'T permanently set u. We'll reset u after.
        } else {
            colsol[j] = -1;
        }
    }
    for (int i = 0; i < n; ++i) u[i] = 0.0;

    // REDUCTION TRANSFER
    int numfree = 0;
    for (int i = 0; i < n; ++i) {
        int j = rowsol[i];
        if (j == -1) free_rows[numfree++] = i;
        else {
            const double* row = C + (size_t)i * n;
            double minv = BIG;
            for (int j2 = 0; j2 < n; ++j2) if (j2 != j) {
                double h = row[j2] - v[j2];
                if (h < minv) minv = h;
            }
            v[j] = row[j] - minv;
        }
    }

    // AUGMENTING ROW REDUCTION (2 passes)
    for (int pass = 0; pass < 2; ++pass) {
        int k = 0, prv = numfree;
        numfree = 0;
        while (k < prv) {
            int i = free_rows[k++];
            const double* row = C + (size_t)i * n;
            double umin = row[0] - v[0];
            int j1 = 0;
            double usubmin = BIG;
            int j2 = -1;
            for (int j = 1; j < n; ++j) {
                double h = row[j] - v[j];
                if (h < usubmin) {
                    if (h >= umin) { usubmin = h; j2 = j; }
                    else { usubmin = umin; umin = h; j2 = j1; j1 = j; }
                }
            }
            int i0 = colsol[j1];
            if (umin < usubmin) v[j1] -= (usubmin - umin);
            else if (i0 >= 0 && j2 >= 0) { j1 = j2; i0 = colsol[j1]; }
            rowsol[i] = j1;
            colsol[j1] = i;
            if (i0 >= 0) {
                if (umin < usubmin) free_rows[--k] = i0;
                else free_rows[numfree++] = i0;
            }
        }
    }

    // AUGMENT
    for (int f = 0; f < numfree; ++f) {
        int freerow = free_rows[f];
        const double* frow = C + (size_t)freerow * n;
        for (int j = 0; j < n; ++j) {
            d[j] = frow[j] - v[j];
            pred[j] = freerow;
            collist[j] = j;
        }
        int low = 0, up = 0;
        double minv = 0;
        int endofpath = -1;
        bool found = false;
        while (!found) {
            if (up == low) {
                // find new minimum among collist[up..n)
                minv = d[collist[up]];
                int up2 = up + 1;
                for (int k = up + 1; k < n; ++k) {
                    int j = collist[k];
                    double h = d[j];
                    if (h <= minv) {
                        if (h < minv) { up2 = up; minv = h; }
                        collist[k] = collist[up2];
                        collist[up2++] = j;
                    }
                }
                up = up2;
                for (int k = low; k < up; ++k) {
                    if (colsol[collist[k]] < 0) {
                        endofpath = collist[k];
                        found = true;
                        break;
                    }
                }
                if (found) break;
            }
            // expand from columns in [low, up)
            int up_begin = up;
            for (int kk = low; kk < up_begin; ++kk) {
                int j1 = collist[kk];
                int i = colsol[j1];
                const double* row = C + (size_t)i * n;
                double base = row[j1] - v[j1] - minv;
                for (int k = up; k < n; ++k) {
                    int j = collist[k];
                    double h = row[j] - v[j] - base;
                    if (h < d[j]) {
                        pred[j] = i;
                        d[j] = h;
                        if (h == minv) {
                            if (colsol[j] < 0) {
                                endofpath = j;
                                found = true;
                                // move j into scanned set so dual update includes it
                                collist[k] = collist[up];
                                collist[up++] = j;
                                goto dual_update;
                            }
                            collist[k] = collist[up];
                            collist[up++] = j;
                        }
                    }
                }
                if (found) break;
            }
            if (found) break;
            low = up;
            if (low >= n) {
                // should not happen
                endofpath = collist[0];
                found = true;
            }
        }
    dual_update:
        for (int k = 0; k < up; ++k) {
            int j = collist[k];
            v[j] += d[j] - minv;
        }
        int i = -1;
        int j = endofpath;
        while (i != freerow) {
            i = pred[j];
            colsol[j] = i;
            int h = rowsol[i];
            rowsol[i] = j;
            j = h;
        }
    }
    return numfree;
}

int main() {
    int n = 200;
    mt19937 rng(1);
    uniform_real_distribution<double> unif(0, 1);
    vector<double> X(n*2), Y(n*2), M(n*(size_t)n);
    for (int i=0;i<n*2;i++){X[i]=unif(rng); Y[i]=unif(rng);}
    for (int i=0;i<n;i++) for (int j=0;j<n;j++) {
        double dx=X[2*i]-Y[2*j], dy=X[2*i+1]-Y[2*j+1];
        M[(size_t)i*n+j]=hypot(dx,dy);
    }
    vector<int> rowsol(n);
    auto t0=chrono::high_resolution_clock::now();
    int nf=lap(n, M.data(), rowsol.data());
    auto t1=chrono::high_resolution_clock::now();
    double cost=0; int bad=0; vector<int> seen(n,0);
    for (int i=0;i<n;i++) {
        if (rowsol[i]<0 || rowsol[i]>=n || seen[rowsol[i]]++) bad++;
        else cost += M[(size_t)i*n+rowsol[i]];
    }
    cout<<"n "<<n<<" time "<<chrono::duration<double>(t1-t0).count()<<" cost "<<cost<<" nf "<<nf<<" bad "<<bad<<"\n";

    n=600;
    X.assign(n*2,0); Y.assign(n*2,0); M.assign(n*(size_t)n,0); rowsol.assign(n,0);
    for (int i=0;i<n*2;i++){X[i]=unif(rng); Y[i]=unif(rng);}
    for (int i=0;i<n;i++) for (int j=0;j<n;j++) {
        double dx=X[2*i]-Y[2*j], dy=X[2*i+1]-Y[2*j+1];
        M[(size_t)i*n+j]=hypot(dx,dy);
    }
    t0=chrono::high_resolution_clock::now();
    nf=lap(n, M.data(), rowsol.data());
    t1=chrono::high_resolution_clock::now();
    cost=0; bad=0; seen.assign(n,0);
    for (int i=0;i<n;i++) {
        if (rowsol[i]<0||rowsol[i]>=n||seen[rowsol[i]]++) bad++;
        else cost+=M[(size_t)i*n+rowsol[i]];
    }
    cout<<"n "<<n<<" time "<<chrono::duration<double>(t1-t0).count()<<" cost "<<cost<<" nf "<<nf<<" bad "<<bad<<"\n";
}
