    double cost=0; vector<int> seen(n,0); int bad=0;
    for (int i=0;i<n;i++) {
        if (rowsol[i]<0||seen[rowsol[i]]++) bad++;
        else cost += M[(size_t)i*n+rowsol[i]];
    }
    cout<<"reduction-only nf="<<nf<<" bad="<<bad<<" cost="<<cost<<"\n";
    // save matrix and assignment
    ofstream f("M200.bin", ios::binary);
    f.write((char*)M.data(), M.size()*sizeof(double));
    ofstream g("asg200.bin", ios::binary);
    g.write((char*)rowsol.data(), n*sizeof(int));
}
