#include <cmath>
#include <vector>
#include <iostream>
#include <chrono>
#include <random>
using namespace std;

int reduce_only(int n, const double* C, int* rowsol) {
    const double BIG = 1e18;
    vector<double> v(n);
    vector<int> colsol(n, -1), free_rows(n);
    for (int i = 0; i < n; ++i) rowsol[i] = -1;
    for (int j = n - 1; j >= 0; --j) {
        double minv = C[j];
        int imin = 0;
        for (int i = 1; i < n; ++i) {
            double c = C[(size_t)i * n + j];
            if (c < minv) { minv = c; imin = i; }
        }
        v[j] = minv;
        if (rowsol[imin] == -1) { rowsol[imin] = j; colsol[j] = imin; }
    }
    int numfree = 0;
    for (int i = 0; i < n; ++i) {
        int j = rowsol[i];
        if (j == -1) free_rows[numfree++] = i;
        else {
            const double* row = C + (size_t)i * n;
            double minv = BIG;
            for (int j2 = 0; j2 < n; ++j2) if (j2 != j) {
                double h = row[j2] - v[j2];
                if (h < minv) minv = h;
            }
            v[j] = row[j] - minv;
        }
    }
    int reprocess = 0;
    for (int pass = 0; pass < 2; ++pass) {
        int k = 0, prv = numfree;
        numfree = 0;
        while (k < prv) {
            int i = free_rows[k++];
            const double* row = C + (size_t)i * n;
            double umin = row[0] - v[0];
            int j1 = 0; double usubmin = BIG; int j2 = -1;
            for (int j = 1; j < n; ++j) {
                double h = row[j] - v[j];
                if (h < usubmin) {
                    if (h >= umin) { usubmin = h; j2 = j; }
                    else { usubmin = umin; umin = h; j2 = j1; j1 = j; }
                }
            }
            int i0 = colsol[j1];
            if (umin < usubmin) v[j1] -= (usubmin - umin);
            else if (i0 >= 0 && j2 >= 0) { j1 = j2; i0 = colsol[j1]; }
            rowsol[i] = j1;
            colsol[j1] = i;
            if (i0 >= 0) {
                if (umin < usubmin) { free_rows[--k] = i0; reprocess++; }
                else free_rows[numfree++] = i0;
            }
        }
    }
    cout << "reprocess " << reprocess << " final free " << numfree << "\n";
    return numfree;
}

int main() {
    for (int n : {200, 400, 600}) {
        mt19937 rng(1);
        uniform_real_distribution<double> unif(0,1);
        vector<double> X(n*2), Y(n*2), M(n*(size_t)n);
