#include <cmath>
#include <vector>
#include <iostream>
#include <chrono>
#include <random>
#include <fstream>
using namespace std;

struct Res { double cost; int bad; int aug; double time; };

Res solve(int n, const double* C) {
    const double BIG = 1e18;
    vector<double> v(n), d(n);
    vector<int> rowsol(n, -1), colsol(n, -1), pred(n), free_rows(n), collist(n);
    auto t0 = chrono::high_resolution_clock::now();
    for (int j = n - 1; j >= 0; --j) {
        double minv = C[j];
        int imin = 0;
        for (int i = 1; i < n; ++i) {
            double c = C[(size_t)i * n + j];
            if (c < minv) { minv = c; imin = i; }
        }
        v[j] = minv;
        if (rowsol[imin] == -1) { rowsol[imin] = j; colsol[j] = imin; }
    }
    int numfree = 0;
    for (int i = 0; i < n; ++i) {
        int j = rowsol[i];
        if (j == -1) free_rows[numfree++] = i;
        else {
            const double* row = C + (size_t)i * n;
            double minv = BIG;
            for (int j2 = 0; j2 < n; ++j2) if (j2 != j) {
                double h = row[j2] - v[j2];
                if (h < minv) minv = h;
            }
            v[j] = row[j] - minv;
        }
    }
    // ONE augmenting row reduction pass, no repeated reprocess of the same row more than n times total per pass
    for (int pass = 0; pass < 2; ++pass) {
        int k = 0, prv = numfree;
        numfree = 0;
        int guard = 0;
        int guardmax = n * 4;
        while (k < prv && guard < guardmax) {
            int i = free_rows[k++];
            guard++;
            const double* row = C + (size_t)i * n;
            double umin = row[0] - v[0];
            int j1 = 0; double usubmin = BIG; int j2 = -1;
            for (int j = 1; j < n; ++j) {
                double h = row[j] - v[j];
                if (h < usubmin) {
                    if (h >= umin) { usubmin = h; j2 = j; }
                    else { usubmin = umin; umin = h; j2 = j1; j1 = j; }
                }
            }
            int i0 = colsol[j1];
            if (umin < usubmin) v[j1] -= (usubmin - umin);
            else if (i0 >= 0 && j2 >= 0) { j1 = j2; i0 = colsol[j1]; }
            // unmatch previous owner of j1 if any, and unmatch i's old? i was free
            if (rowsol[i] >= 0 && rowsol[i] != j1 && colsol[rowsol[i]] == i) colsol[rowsol[i]] = -1;
            rowsol[i] = j1;
            colsol[j1] = i;
            if (i0 >= 0 && i0 != i) {
                rowsol[i0] = -1;
                if (umin < usubmin && guard < guardmax) free_rows[--k] = i0;
                else free_rows[numfree++] = i0;
            }
        }
        // any not processed stay free
        while (k < prv) free_rows[numfree++] = free_rows[k++];
    }
    int aug = numfree;
    // shortest augmenting paths for remaining free rows
    for (int f = 0; f < numfree; ++f) {
        int freerow = free_rows[f];
        const double* frow = C + (size_t)freerow * n;
        for (int j = 0; j < n; ++j) {
            d[j] = frow[j] - v[j];
            pred[j] = freerow;
            collist[j] = j;
        }
        int low = 0, up = 0, endofpath = -1;
        double minv = 0;
        bool found = false;
        while (!found) {
            if (up == low) {
                minv = d[collist[up]];
                int up2 = up + 1;
                for (int k = up + 1; k < n; ++k) {
                    int j = collist[k];
                    double h = d[j];
                    if (h <= minv) {
                        if (h < minv) { up2 = up; minv = h; }
                        collist[k] = collist[up2];
                        collist[up2++] = j;
                    }
                }
                up = up2;
                for (int k = low; k < up; ++k) if (colsol[collist[k]] < 0) {
                    endofpath = collist[k]; found = true; break;
                }
                if (found) break;
            }
            int up_begin = up;
            for (int kk = low; kk < up_begin && !found; ++kk) {
                int j1 = collist[kk];
                int i = colsol[j1];
                if (i < 0) { endofpath = j1; found = true; break; }
                const double* row = C + (size_t)i * n;
                double base = row[j1] - v[j1] - minv;
                for (int k = up; k < n; ++k) {
                    int j = collist[k];
                    double h = row[j] - v[j] - base;
                    if (h < d[j]) {
                        pred[j] = i;
                        d[j] = h;
                        if (h == minv) {
                            if (colsol[j] < 0) {
                                endofpath = j; found = true;
                                collist[k] = collist[up]; collist[up++] = j;
                                break;
                            }
                            collist[k] = collist[up];
                            collist[up++] = j;
                        }
                    }
                }
            }
            if (found) break;
            low = up;
            if (low >= n) { endofpath = -1; break; }
        }
        if (endofpath < 0) continue;
        for (int k = 0; k < up; ++k) {
            int j = collist[k];
            v[j] += d[j] - minv;
        }
        int i = -1, j = endofpath;
        while (i != freerow) {
            i = pred[j];
            colsol[j] = i;
            int h = rowsol[i];
            rowsol[i] = j;
            j = h;
            if (j < 0) break;
        }
    }
    auto t1 = chrono::high_resolution_clock::now();
    double cost = 0; int bad = 0; vector<int> seen(n, 0);
    for (int i = 0; i < n; ++i) {
        int j = rowsol[i];
        if (j < 0 || j >= n || seen[j]++) bad++;
        else cost += C[(size_t)i * n + j];
    }
    return {cost, bad, aug, chrono::duration<double>(t1-t0).count()};
}

int main() {
    for (int n : {100, 200, 400, 600}) {
        mt19937 rng(1);
        uniform_real_distribution<double> unif(0,1);
        vector<double> X(n*2), Y(n*2), M(n*(size_t)n);
        for (int i=0;i<n*2;i++){X[i]=unif(rng); Y[i]=unif(rng);}
        for (int i=0;i<n;i++) for (int j=0;j<n;j++) {
            double dx=X[2*i]-Y[2*j], dy=X[2*i+1]-Y[2*j+1];
            M[(size_t)i*n+j]=sqrt(dx*dx+dy*dy);
        }
        // save for scipy compare n=200,600
        Res r = solve(n, M.data());
        cout << "n " << n << " time " << r.time << " cost " << r.cost << " bad " << r.bad << " aug_in " << r.aug << "\n";
        if (n==200 || n==600) {
            ofstream f(n==200?"M200.bin":"M600.bin", ios::binary);
            f.write((char*)M.data(), M.size()*sizeof(double));
        }
    }
}
