{"command":"cat > geo_auc.cpp << 'EOF'
#include <vector>
#include <cmath>
#include <algorithm>
#include <iostream>
#include <chrono>
#include <random>
#include <cstring>
#include <cstdint>
using namespace std;

struct Pt { double x, y; };

struct KD {
    struct Node { int idx; int left, right; double mx, my, Mx, My; };
    vector<Node> nodes;
    vector<Pt> pts;
    int root = -1;
    int build(vector<int>& idx, int l, int r, int depth) {
        if (l >= r) return -1;
        int axis = depth & 1;
        int mid = (l + r) / 2;
        nth_element(idx.begin()+l, idx.begin()+mid, idx.begin()+r, [&](int a, int b){
            return axis ? pts[a].y < pts[b].y : pts[a].x < pts[b].x;
        });
        int id = (int)nodes.size();
        nodes.push_back({idx[mid], -1, -1, 0,0,0,0});
        nodes[id].left = build(idx, l, mid, depth+1);
        nodes[id].right = build(idx, mid+1, r, depth+1);
        double mx=pts[idx[mid]].x, my=pts[idx[mid]].y, Mx=mx, My=my;
        auto acc=[&](int c){ if(c<0) return; mx=min(mx,nodes[c].mx); my=min(my,nodes[c].my); Mx=max(Mx,nodes[c].Mx); My=max(My,nodes[c].My); };
        acc(nodes[id].left); acc(nodes[id].right);
        nodes[id].mx=mx; nodes[id].my=my; nodes[id].Mx=Mx; nodes[id].My=My;
        return id;
    }
    void init(const vector<Pt>& p) {
        pts=p; nodes.clear(); nodes.reserve(p.size());
        vector<int> idx(p.size());
        iota_wrap(idx);
        root=build(idx, 0, (int)p.size(), 0);
    }
    void iota_wrap(vector<int>& idx){ for(int i=0;i<(int)idx.size();++i) idx[i]=i; }
    // k nearest (brute within tree) — return indices
    void knn(double x, double y, int k, vector<int>& out, vector<double>& dout) const {
        out.clear(); dout.clear();
        // max-heap of size k stored as vectors
        vector<pair<double,int>> heap;
        heap.reserve(k);
        auto consider=[&](int i, double d2){
            if ((int)heap.size() < k) {
                heap.push_back({d2,i});
                push_heap(heap.begin(), heap.end());
            } else if (d2 < heap.front().first) {
                pop_heap(heap.begin(), heap.end());
                heap.back()={d2,i};
                push_heap(heap.begin(), heap.end());
            }
        };
        // recursive
        const KD* self=this;
        function_search(root, x, y, k, heap);
        for (auto& p : heap) { out.push_back(p.second); dout.push_back(sqrt(p.first)); }
    }
    void function_search(int node, double x, double y, int k, vector<pair<double,int>>& heap) const {
        if (node < 0) return;
        const Node& nd = nodes[node];
        // prune by bbox
        double dx=0, dy=0;
        if (x < nd.mx) dx = nd.mx - x; else if (x > nd.Mx) dx = x - nd.Mx;
        if (y < nd.my) dy = nd.my - y; else if (y > nd.My) dy = y - nd.My;
        double d2box = dx*dx+dy*dy;
        if ((int)heap.size()==k && d2box >= heap.front().first) return;
        double px=pts[nd.idx].x, py=pts[nd.idx].y;
        double ddx=x-px, ddy=y-py;
        double d2=ddx*ddx+ddy*ddy;
        if ((int)heap.size() < k) {
            heap.push_back({d2, nd.idx});
            push_heap(heap.begin(), heap.end());
        } else if (d2 < heap.front().first) {
            pop_heap(heap.begin(), heap.end());
            heap.back()={d2, nd.idx};
            push_heap(heap.begin(), heap.end());
        }
        function_search(nd.left, x, y, k, heap);
        function_search(nd.right, x, y, k, heap);
    }
};

// Auction over kNN candidates, with fallback full scan if a bidder's best is at the boundary (eps-suboptimal possibly outside).
bool auction(const vector<Pt>& X, const vector<Pt>& Y, int* assign, double eps_final, int k) {
    int n = (int)X.size();
    KD tree; tree.init(Y);
    vector<double> price(n, 0.0);
    vector<int> owner(n, -1);
    vector<int> q(n);
    vector<int> neigh(k);
    vector<double> ndist(k);
    double eps = 0.25;
    int scales = 0;
    while (true) {
        fill(owner.begin(), owner.end(), -1);
        int qh=0, qt=n;
        for (int i=0;i<n;i++) q[i]=i;
        int unassigned=n;
        long long guard=0;
        long long maxg = (long long)n * k * 50;
        bool failed=false;
        while (unassigned) {
            if (++guard > maxg) { failed=true; break; }
            int i=q[qh++];
            if (qh> (int)q.size()-2) {
                // compact
                int sz=qt-qh;
                if (sz<0) {failed=true; break;}
                memmove(q.data(), q.data()+qh, sz*sizeof(int));
                qh=0; qt=sz;
                if (qt+8 > (int)q.size()) q.resize(q.size()*2+8);
            }
            tree.knn(X[i].x, X[i].y, k, neigh, ndist);
            // find best and second among neighbors using -dist - price
            int best_j = neigh[0];
            double best = -ndist[0] - price[best_j];
            double second = -1e300;
            double worst = ndist[0];
            for (int t=0;t<k;t++) {
                int j=neigh[t];
                double v = -ndist[t] - price[j];
                if (ndist[t] > worst) worst = ndist[t];
                if (v > best) { second=best; best=v; best_j=j; }
                else if (v > second) second = v;
            }
            // If the bid increment would reach beyond the kNN radius, the true second-best might be outside.
            // bid_inc = best - second + eps. The profit gap to an outside point is at most best - (-worst - price_min_outside).
            // Conservative: if second is within eps of -worst - min_price_outside, do a full scan.
            // Simpler conservative: always full-scan if best is the farthest neighbor (on the boundary) OR price differences large.
            // For correctness of final scale, do full scan when (best - second) + eps > (something).
            // We'll full-scan if the k-th neighbor profit could beat second.
            // min possible outside value = -worst - max_price? outside dist >= worst, so -dist - price <= -worst - min_price.
            // If -worst - min_price <= second, outside cannot beat second. 
            double min_price = 0; // prices are >= 0 in auction? bids increase prices from 0, yes prices nonnegative.
            // price starts 0 and only increases. Outside value <= -worst - 0 = -worst.
            // If -worst <= second, no outside point can be better than second. Good.
            if (-worst > second) {
                // full scan
                best = -1e300; second = -1e300; best_j=0;
                double xi=X[i].x, yi=X[i].y;
                for (int j=0;j<n;j++) {
                    double dx=xi-Y[j].x, dy=yi-Y[j].y;
                    double v = -sqrt(dx*dx+dy*dy) - price[j];
                    if (v > best) { second=best; best=v; best_j=j; }
                    else if (v > second) second=v;
                }
            }
            double bid = price[best_j] + (best - second) + eps;
            int prev = owner[best_j];
            if (prev >= 0) {
                if (qt >= (int)q.size()) q.resize(q.size()*2);
                q[qt++] = prev;
            } else unassigned--;
            owner[best_j]=i;
            assign[i]=best_j;
            price[best_j]=bid;
        }
        if (failed) return false;
        scales++;
        if (eps <= eps_final * 1.0000001) break;
        eps *= 0.25;
        if (eps < eps_final) eps = eps_final;
    }
    return true;
}

int main() {
    int n=600;
    mt19937 rng(1);
    uniform_real_distribution<double> unif(0,1);
    vector<Pt> X(n), Y(n);
    for (int i=0;i<n;i++){ X[i]={unif(rng),unif(rng)}; Y[i]={unif(rng),unif(rng)}; }
    vector<int> asg(n);
    for (int k : {8, 16, 32}) {
        auto t0=chrono::high_resolution_clock::now();
        bool ok=auction(X,Y,asg.data(), 1e-8, k);
        auto t1=chrono::high_resolution_clock::now();
        double cost=0;
        for (int i=0;i<n;i++){ double dx=X[i].x-Y[asg[i]].x, dy=X[i].y-Y[asg[i]].y; cost+=sqrt(dx*dx+dy*dy); }
        cout<<"k "<<k<<" ok "<<ok<<" time "<<chrono::duration<double>(t1-t0).count()<<" cost "<<cost<<"\n";
    }
}
