#include <cmath>
#include <vector>
#include <iostream>
#include <chrono>
#include <random>
#include <thread>
#include <atomic>
using namespace std;

// Parallel Hungarian (Kuhn-Munkres) — the inner j-loop is parallelized per row augmentation.
// This is the O(n^3) algorithm. Parallelism over columns.

void hungarian_par(const double* M, int n, int* assign, int threads) {
    vector<double> u(n+1, 0.0), v(n+1, 0.0);
    vector<int> p(n+1, 0), way(n+1, 0);
    vector<double> minv(n+1);
    vector<char> used(n+1);
    for (int i = 1; i <= n; ++i) {
        p[0] = i;
        int j0 = 0;
        fill(minv.begin(), minv.end(), 1e18);
        fill(used.begin(), used.end(), 0);
        do {
            used[j0] = 1;
            int i0 = p[j0];
            double delta = 1e18;
            int j1 = 0;
            const double* row = M + (size_t)(i0-1) * n;
            double ui = u[i0];
            // parallel scan
            int T = threads;
            vector<double> local_delta(T, 1e18);
            vector<int> local_j1(T, 0);
            vector<thread> pool;
            int chunk = (n + T - 1) / T;
            for (int t = 0; t < T; ++t) {
                int begin = 1 + t * chunk;
                int end = min(n+1, begin + chunk);
                pool.emplace_back([&, t, begin, end]() {
                    double ld = 1e18; int lj = 0;
                    for (int j = begin; j < end; ++j) {
                        if (used[j]) continue;
                        double cur = row[j-1] - ui - v[j];
                        if (cur < minv[j]) {
                            minv[j] = cur;
                            way[j] = j0;
                        }
                        if (minv[j] < ld) { ld = minv[j]; lj = j; }
                    }
                    local_delta[t] = ld;
                    local_j1[t] = lj;
                });
            }
            for (auto& th : pool) th.join();
            for (int t = 0; t < T; ++t) if (local_delta[t] < delta) { delta = local_delta[t]; j1 = local_j1[t]; }
            for (int j = 0; j <= n; ++j) {
