#include <vector>
#include <cmath>
#include <algorithm>
#include <iostream>
#include <chrono>
#include <random>
#include <cstring>
#include <cstdint>
using namespace std;

// Dense epsilon-scaling auction, minimization, float costs stored as double.
// Processes one bidder at a time but with a tight inner loop.
// eps_final = 1/(n+1) after scaling costs by SCALE (integer-equivalent).

bool auction(const double* cost, int n, int* assign, double eps_final) {
    vector<double> price(n, 0.0);
    vector<int> owner(n, -1);
    vector<int> q;
    q.resize(n * 2);
    // initial eps
    double mx = cost[0], mn = cost[0];
    // sample for range
    for (int i = 0; i < n; i += 7) {
        double v = cost[(size_t)i * n + (i % n)];
        if (v > mx) mx = v;
        if (v < mn) mn = v;
    }
    double eps = (mx - mn) / 2.0;
    if (eps < eps_final) eps = eps_final;

    int scales = 0;
    while (true) {
        fill(owner.begin(), owner.end(), -1);
        int qh = 0, qt = n;
        for (int i = 0; i < n; ++i) q[i] = i;
        int unassigned = n;
        long long guard = 0;
        long long maxg = (long long)n * n * 2;
        while (unassigned) {
            if (++guard > maxg) return false;
            int i = q[qh++];
            if (qh > (int)q.size() / 2) {
                int sz = qt - qh;
                memmove(q.data(), q.data() + qh, sz * sizeof(int));
                qh = 0; qt = sz;
            }
            const double* row = cost + (size_t)i * n;
            int best_j = 0;
            double best = -row[0] - price[0];
            double second = -1e300;
            for (int j = 1; j < n; ++j) {
                double v = -row[j] - price[j];
                if (v > best) { second = best; best = v; best_j = j; }
                else if (v > second) second = v;
            }
            double bid_inc = best - second + eps;
            price[best_j] += bid_inc;
            int prev = owner[best_j];
            if (prev >= 0) {
                if (qt >= (int)q.size()) q.resize(max(qt + n, (int)q.size() * 2));
                q[qt++] = prev;
            } else {
                --unassigned;
            }
            owner[best_j] = i;
            assign[i] = best_j;
        }
        ++scales;
        if (eps <= eps_final * 1.0000001) break;
        eps *= 0.2;
        if (eps < eps_final) eps = eps_final;
    }
    cerr << "scales " << scales << "\n";
    return true;
}

int main() {
    int n = 600;
    mt19937 rng(1);
    uniform_real_distribution<double> unif(0, 1);
    vector<double> X(n * 2), Y(n * 2), M(n * (size_t)n);
    for (int i = 0; i < n * 2; ++i) { X[i] = unif(rng); Y[i] = unif(rng); }
    double scale = 1e6;
    for (int i = 0; i < n; ++i) for (int j = 0; j < n; ++j) {
        double dx = X[2 * i] - Y[2 * j], dy = X[2 * i + 1] - Y[2 * j + 1];
        M[(size_t)i * n + j] = llround(sqrt(dx * dx + dy * dy) * scale);
    }
    vector<int> asg(n);
    bool ok = auction(M.data(), n, asg.data(), 1.0);
    auto t0 = chrono::high_resolution_clock::now();
    int reps = 3;
    for (int r = 0; r < reps; ++r) ok = auction(M.data(), n, asg.data(), 1.0);
    auto t1 = chrono::high_resolution_clock::now();
    cout << "ok " << ok << " time " << chrono::duration<double>(t1 - t0).count() / reps << "\n";
}
